private val cache = mutableMapOf<String, ImageVector>()

/**
 * The logo for a stored brand slug, or null when there is none — in which case
 * the badge shows the service's initial, exactly as `BrandLogo` does.
 */
fun brandIcon(slug: String?): ImageVector? {
    val path = BRAND_PATHS[slug ?: return null] ?: return null
    return cache.getOrPut(slug) {
        ImageVector.Builder(
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        ).apply {
            addPath(
                pathData = PathParser().parsePathString(path).toNodes(),
                fill = SolidColor(Color.Black),
            )
        }.build()
    }
}
